<?php declare(strict_types=1); namespace App\Repositories; use PDO; final class LiquidityPoolRepository{private $pdo; public function __construct(?PDO $pdo=null){$this->pdo=$pdo??\App\Core\Database::connection();} public function createInitialState($sid){$this->pdo->prepare('INSERT INTO liquidity_pool_state (session_id) VALUES (?)')->execute([$sid]);} public function findBySessionId($sid){$s=$this->pdo->prepare('SELECT * FROM liquidity_pool_state WHERE session_id=?');$s->execute([$sid]);return $s->fetch()?:null;} public function updateState($sid,$pn,$ts,$tv,$yps,$st){$s=$this->pdo->prepare('UPDATE liquidity_pool_state SET pool_nfts=?, total_shares=?, total_value=?, yield_per_share=?, status=? WHERE session_id=?');$s->execute([$pn,$ts,$tv,$yps,$st,$sid]);}}
